      if (DD.door(e, { x: e.x - 2, y: e.y, w: e.w + 4, h: e.h })) { e.dwell = 0; e.tele = { f0: G.frame }; G.hitstop = 8; p.vx = 0; DD.SFX.tick && DD.SFX.tick(); }   // press Down to go in, like every other world's room doors; the way back too
