      if (!e.out) { const by = Y - 10 + Math.round(Math.abs(Math.sin(G.frame / 10)) * 3); ctx.fillStyle = '#ffe680'; ctx.fillRect(X + 5, by, 6, 2); ctx.fillRect(X + 6, by + 2, 4, 2); ctx.fillRect(X + 7, by + 4, 2, 2); }   // a bobbing Down arrow
      const a = 0.55 + 0.25 * Math.sin(G.frame / 7), w = e.dwell / (e.out ? 14 : 36);
      ctx.fillStyle = INK; ctx.fillRect(X - 2, Y - 2, e.w + 4, e.h + 2);
